import { tz } from "@date-fns/tz";
import { describe, expect, it } from "vitest";
import { isSameHour } from "../index.js";

describe("isSameHour regressions", () => {
  it("returns true for different minutes and seconds in the same hour", () => {
    expect(
      isSameHour(
        new Date(2024, 0, 15, 9, 4, 12),
        new Date(2024, 0, 15, 9, 58, 47),
      ),
    ).toBe(true);
  });

  it("preserves distinctions across hours, days, months, and years", () => {
    const date = new Date(2024, 0, 15, 9, 0);

    expect(isSameHour(date, new Date(2024, 0, 15, 10, 0))).toBe(false);
    expect(isSameHour(date, new Date(2024, 0, 16, 9, 0))).toBe(false);
    expect(isSameHour(date, new Date(2024, 1, 15, 9, 0))).toBe(false);
    expect(isSameHour(date, new Date(2025, 0, 15, 9, 0))).toBe(false);
  });

  it("accepts timestamp and string inputs", () => {
    expect(
      isSameHour(
        new Date("2024-04-10T07:00:00Z").getTime(),
        "2024-04-10T07:45:00Z",
      ),
    ).toBe(true);
  });

  it("returns false for invalid dates without mutating inputs", () => {
    const date = new Date(2024, 0, 15, 9, 37, 12);
    const originalTime = date.getTime();

    expect(isSameHour(date, new Date(NaN))).toBe(false);
    expect(date.getTime()).toBe(originalTime);
  });

  it("normalizes string inputs using the provided timezone context", () => {
    expect(
      isSameHour("2024-04-10T07:30:00Z", "2024-04-10T08:00:00Z", {
        in: tz("Asia/Kolkata"),
      }),
    ).toBe(true);
  });
});

