import { describe, expect, it } from "vitest";
import { isSameHour } from "../index.js";

describe("isSameHour regressions", () => {
  it("returns true for different minutes and seconds within the same hour", () => {
    expect(
      isSameHour(
        new Date(2014, 8, 4, 6, 0, 1),
        new Date(2014, 8, 4, 6, 59, 59),
      ),
    ).toBe(true);
  });

  it("returns false for the same hour on different days", () => {
    expect(
      isSameHour(
        new Date(2014, 8, 4, 6, 15),
        new Date(2014, 8, 5, 6, 45),
      ),
    ).toBe(false);
  });

  it("returns false for the same hour on different months and years", () => {
    expect(
      isSameHour(
        new Date(2014, 8, 4, 6, 15),
        new Date(2015, 9, 4, 6, 45),
      ),
    ).toBe(false);
  });
});

